import assert from 'node:assert/strict';
import test from 'node:test';

import { validateLess } from '../scripts/check-public-less.mjs';

const validate = (source) => validateLess(source, 'fixture.less');

test('accepts a top-level BEM selector and a compliant layout rule', () => {
  assert.deepEqual(
    validate(`
.vehicle-card__title--compact {
  width: 100%;
  padding-left: 12px;
  padding-right: 12px;
  box-sizing: border-box;
}
`),
    [],
  );
});

test('rejects forbidden public properties', () => {
  const issues = validate(`
.vehicle-card {
  gap: 12px;
}
`);

  assert.equal(issues.length, 1);
  assert.match(issues[0].message, /gap/);
  assert.equal(issues[0].line, 3);
});

test('rejects nested and compound selectors', () => {
  const issues = validate(`
.vehicle-card {
  .vehicle-card__title {
    color: #111;
  }
}
`);

  assert.ok(issues.some((issue) => issue.rule === 'top-level-single-selector'));
});

test('rejects pseudo selectors, non-BEM selectors, and empty rules', () => {
  const issues = validate(`
.vehicle-card:hover {
  color: #111;
}

.vehicle-card__title__label {
  color: #111;
}

.vehicle-card__empty {
}
`);

  assert.ok(issues.some((issue) => issue.rule === 'bem-selector'));
  assert.ok(issues.some((issue) => issue.rule === 'bem-selector'));
  assert.ok(issues.some((issue) => issue.rule === 'empty-rule'));
});

test('allows a non-RN property inside a lowercase #ifndef rn block', () => {
  assert.deepEqual(
    validate(`
.vehicle-card {
  /* #ifndef rn */
  box-shadow: 0 2px 4px #000;
  /* #endif */
}
`),
    [],
  );
});

test('allows multi-platform style conditions and rejects uppercase platform names', () => {
  const valid = validate(`
.vehicle-card {
  /* #ifdef h5 weapp */
  position: fixed;
  /* #endif */
}
`);
  const invalid = validate(`
.vehicle-card {
  /* #ifdef RN */
  color: #111;
  /* #endif */
}
`);

  assert.deepEqual(valid, []);
  assert.ok(invalid.some((issue) => issue.rule === 'platform-condition'));
});

test('requires border-box for width 100 percent with horizontal padding', () => {
  const issues = validate(`
.vehicle-card {
  width: 100%;
  padding-left: 12px;
}
`);

  assert.ok(issues.some((issue) => issue.rule === 'width-padding-box-sizing'));
});

test('requires a px value for public line-height', () => {
  const issues = validate(`
.vehicle-card__title {
  line-height: 1.5;
}

.vehicle-card__subtitle {
  line-height: normal;
}

.vehicle-card__caption {
  line-height: 120%;
}
`);

  assert.equal(issues.filter((issue) => issue.rule === 'line-height-px').length, 3);
});

# 同排等宽布局参考

## 适用条件

同一行放 N 个（常见 2 个）等宽等高的入口卡片；任一卡片可因业务条件缺席，缺席时剩余入口回退为整行形态（横条或独占卡）。典型实例：详情页金融入口 + 置换入口同排。

同一 block 因此存在**互斥形态**（如整行横条 `--bar` 与同排卡片 `--entry-card`），形态由 JSX 分支决定，每种形态都有自己的正向 modifier。

## JSX 结构

```tsx
<View className="block__entry-row">
  <View className={`block${isPaired ? ' block--entry-card' : ' block--bar'}`} />
</View>
```

## Less

```less
/* 行容器：只管方向与对齐，不管间距 */
.block__entry-row {
  width: 100%;
  display: flex;
  flex-direction: row;
  align-items: stretch;
}

/* 卡片形态：等分 + 宽度下限 + 固定高 */
.block--entry-card {
  flex: 1;
  min-width: 187px;
  height: 112px;
  margin-right: 16px; /* 末位卡片不加间距 */
  overflow: hidden;
  box-sizing: border-box;
}

/* 整行形态：与卡片形态互斥，显式命名 */
.block--bar {
  height: 48px;
}
```

```

## 缺席回退

卡片缺席时由 JSX 选择 `block--bar`，不使用 `:not()` 或后代选择器表达回退状态。

## 三端注意事项

按布局意图查表选路由；「禁止路由」列的写法 H5 常能跑，RN 静默失效。

| 布局意图 | 三端兼容路由 | 禁止路由 |
|---|---|---|
| 两卡同排等宽 | 行容器 flex row + **每卡** `flex: 1` + `min-width` | 只写行容器，依赖卡片默认宽度（RN 下各自占满整行） |
| 卡片间距 | 首卡 `margin-right`，多卡用每卡 margin + `--last` 清零 | `gap`；`space-between` 当固定间距用 |
| 同 block 互斥形态 | 每种形态一个正向 modifier，JSX 分支显式同挂 | `:not(.--x)` 表达「非某形态」；默认类 + 形态类覆盖 |
| 子元素随形态变化 | 子元素自身挂 `--modifier`（如 `__icon--entry-card`） | 后代选择器 `.block--x .block__icon` |
| 同排卡片等高 | 行容器 `align-items: stretch` + 卡片显式 `height` | 依赖内容撑高（各端字体/行高差异导致不齐） |
| 卡片渐变背景 | `LinearGradient` 组件包裹内容 | CSS `linear-gradient` |
| 三方组件尺寸（如 `AtIcon` 的 `fontSize`） | 内联 `style` + px 转换函数 | Less 选择器试图命中三方组件内部节点 |
| 内联 `style` 迁 Less（CSS 化） | 顶层 BEM + modifier 承接原条件逻辑 | 把条件逻辑翻译成 `:not()` / 后代选择器 |

